#pragma once

#include <cstdint>
#include <functional>

// H6280InputLine/H6280InputLineState - the HuC6280's externally driven interrupt inputs. The TIQ (timer) request is
// generated by the core's own internal timer and is deliberately NOT
// settable from outside (only IRQ1, IRQ2 and NMI are pins).
enum class H6280InputLine {
    Irq1,  // level-triggered, IRQ1 vector 0xFFF8 (Vapor Trail: the sound-latch data_pending line)
    Irq2,  // level-triggered, IRQ2/BRK vector 0xFFF6 (Vapor Trail: the YM2151 IRQ pin)
    Nmi,   // edge (only the Assert transition latches a request), vector 0xFFFC
};

enum class H6280InputLineState {
    Clear,
    Assert,
};

// IH6280Core - stable, MAME-independent
// Hudson/Hitachi HuC6280 (65C02 + 8-bank MMU + timer + interrupt controller)
// execution interface. Same design idea as IZ80Core/IM68000Core/I8039Core:
// no MAME type ever appears here, every bus access goes through callbacks.
//
// What the core owns (never exposed): the eight memory-mapping registers and
// the logical->physical translation (21-bit physical space), the timer, the
// interrupt mask/status registers, the I/O buffer, and the internal I/O page
// at physical 0x1FE800-0x1FEBFF (PSG - writes are swallowed, this project
// has no PSG), 0x1FEC00-0x1FEFFF (timer), 0x1FF000-0x1FF3FF (K/O port -
// unused here) and 0x1FF400-0x1FF7FF (interrupt mask/status). Everything else
// in the 21-bit physical space goes to the memory callbacks below with the
// physical address.
//
// Time model: Execute() consumes the CPU's own input clock
// (Vapor Trail: 6MHz, i.e. the device clock MAME hands h6280_device). The core
// starts in low-speed mode (4 device clocks per CPU cycle) exactly like
// MAME's h6280_device; CSH/CSL switch it.
class IH6280Core {
public:
    virtual ~IH6280Core() = default;

    using MemoryReadFn = std::function<std::uint8_t(std::uint32_t physicalAddress)>;
    using MemoryWriteFn = std::function<void(std::uint32_t physicalAddress, std::uint8_t value)>;

    // Physical (21-bit) address space outside the core's own I/O page.
    virtual void SetMemoryCallbacks(MemoryReadFn read, MemoryWriteFn write) = 0;

    // MAME's h6280_device::set_timer_scale() ("hack to fix music speed in some
    // Data East games"): multiplies the timer reload value. Vapor Trail uses 2.
    // Takes effect at the next Reset() (MAME applies it in device_reset()) and
    // for every later timer-preload write.
    virtual void SetTimerScale(int scale) = 0;

    // Power-on reset: reads the reset vector (0xFFFE) through the current MMR
    // state (all zero -> physical 0x00FFFE), P = I|B, S = 0x1FF, low-speed mode.
    virtual void Reset() = 0;

    // Executes at least `clockBudget` input clocks (an instruction is never
    // split, so the budget may be exceeded by part of one instruction, never
    // undershot - same rule as the other cores). Returns the clocks consumed.
    virtual std::uint64_t Execute(std::uint64_t clockBudget) = 0;

    virtual void SetInputLine(H6280InputLine line, H6280InputLineState state) = 0;
};
